// Author: MiYu. Original music controls, source RNG/fade fixtures and muted Miles playback.
#include "session.h"
#include "setup.h"
#include <StormLib.h>
#include <bit>
#include <functional>
#include <iostream>

using namespace war3;
namespace {
void require(bool value,const char* message) {if(!value)throw std::runtime_error(message);}
template<class F> void rejects(F run,const char* message) {try{run();}catch(const std::exception& e){require(std::string(e.what()).find(message)!=std::string::npos,"Unexpected music diagnostic");return;}throw std::runtime_error("Invalid music operation accepted");}
void mpq(const fs::path& path,const std::vector<std::pair<std::string,std::string>>& entries) {HANDLE archive=nullptr;require(SFileCreateArchive(path.c_str(),MPQ_CREATE_ARCHIVE_V1,32,&archive),"Cannot create music fixture");struct Close {HANDLE value;~Close(){SFileCloseArchive(value);}}close{archive};for(auto& [name,value]:entries){HANDLE member=nullptr;require(SFileCreateFile(archive,name.c_str(),0,DWORD(value.size()),0,MPQ_FILE_COMPRESS,&member),"Cannot create music fixture member");bool written=SFileWriteFile(member,value.data(),DWORD(value.size()),MPQ_COMPRESSION_ZLIB),finished=SFileFinishFile(member);require(written && finished,"Cannot write music fixture");}}
std::string pcm() {std::string b;auto word=[&](unsigned value,unsigned bytes){while(bytes--){b+=char(value);value>>=8;}};b="RIFF";word(36+2206,4);b+="WAVEfmt ";word(16,4);word(1,2);word(1,2);word(22050,4);word(22050,4);word(1,2);word(8,2);b+="data";word(2206,4);b.append(2206,std::bit_cast<char>(std::uint8_t{128}));return b;}
const std::string track="Sound\\Music\\mp3Music\\Human3.mp3";
const std::string api=R"jass(native SetMapMusic takes string name, boolean random, integer index returns nothing
native ClearMapMusic takes nothing returns nothing
native PlayMusic takes string name returns nothing
native PlayMusicEx takes string name, integer offset, integer fade returns nothing
native StopMusic takes boolean fade returns nothing
native ResumeMusic takes nothing returns nothing
native SetMusicVolume takes integer volume returns nothing
native SetMusicPlayPosition takes integer offset returns nothing
function config takes nothing returns nothing
call SetMapMusic("Music",true,123)
endfunction
function main takes nothing returns nothing
call PlayMusic("Sound\\Music\\mp3Music\\Human3.mp3")
call SetMusicVolume(64)
call SetMusicPlayPosition(500)
call StopMusic(false)
call ResumeMusic()
endfunction
)jass";
}
int wmain(int argc,wchar_t** argv) {
    std::cout<<std::unitbuf;if(argc!=3){std::cerr<<"Usage: war3_music_tests <data-root> <output-root>\n";return 2;}auto output=fs::absolute(argv[2]);fs::create_directories(output);auto scratch=output/(std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64()));fs::create_directories(scratch);unsigned passed=0,failed=0;auto test=[&](const char* name,const std::function<void()>& run){try{run();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cout<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
    try {
        Archives archives(argv[1]);
        test("music_map_configuration_is_lazy_and_preserves_index",[&]{auto root=scratch/L"bare";fs::create_directories(root);mpq(root/L"war3.mpq",{{"unused","x"}});Archives source(root);MusicScene scene(source,0);scene.map("MissingSource",true,8);require(scene.mapName()=="MissingSource" && scene.mapIndex()==-1 && !scene.voice() && scene.tracks().empty(),"Map configuration opened or resolved music");scene.map(std::string(400,'x'),false,-123);require(scene.mapName().size()==259 && scene.mapIndex()==-123,"Source map name bound or signed index differs");scene.map(std::string("abc\0ignored",11),false,3);require(scene.mapName()=="abc","Music name did not stop at native NUL");scene.clear();require(scene.mapName().empty() && scene.mapIndex()==-1,"ClearMapMusic defaults differ");});
        test("music_source_skin_version_race_and_random_selection",[&]{MusicScene scene(archives,123);scene.muted(true);scene.skin("Human",1);scene.play("Music");AudioRandom expected(123);require(scene.tracks().size()==4 && scene.tracks()[0]=="Sound\\Music\\mp3Music\\HumanX1.mp3" && scene.selected()==expected.index(4),"TFT human music source or random index differs");require(scene.voice() && scene.voice()->playing() && scene.voice()->volume()==0,"Source music was not really playing muted");scene.skin("Human",0);scene.play("Music");require(scene.tracks().size()==3 && scene.tracks()[0]=="Sound\\Music\\mp3Music\\Human1.mp3","ROC music version did not use source key");});
        test("music_custom_skin_and_empty_shadow",[&]{auto custom=scratch/L"skin.w3x";mpq(custom,{{"war3mapSkin.txt","[CustomSkin]\nMusic_V1=Sound\\Music\\mp3Music\\Orc1.mp3\nEmpty_V1=\n"}});auto view=archives.fork();view->mountMap(custom);MusicScene scene(*view,1);scene.muted(true);scene.skin("Human");scene.play("Music");require(scene.tracks()==std::vector<std::string>{"Sound\\Music\\mp3Music\\Orc1.mp3"},"Map CustomSkin did not override race/default");auto voice=scene.voice();scene.play("Empty");require(scene.tracks().empty() && scene.voice()==voice && voice->playing(),"Empty defined skin value fell back or stopped active music");});
        test("music_real_seek_pause_resume_repeat_and_clear",[&]{auto device=MilesDevice::open(argv[1]);{MusicScene scene(archives,11);scene.muted(true);scene.play(track);scene.position(1000);auto position=scene.voice()->milliseconds().first;require(position>=990,"Music seek did not reach Miles");auto voice=scene.voice();scene.play(track);require(scene.voice()==voice && scene.voice()->milliseconds().first>=position,"Same music restarted playback");scene.stop(false);require(scene.paused() && !voice->playing(),"StopMusic(false) did not pause");scene.volume(40);scene.muted(false);require(voice->volume()==40,"Paused music volume did not reach Miles");scene.muted(true);scene.resume();require(voice->playing() && !scene.paused() && voice->milliseconds().first>=position,"ResumeMusic lost paused playback position");scene.clear();require(scene.voice()==voice && voice->playing() && scene.mapName().empty() && scene.tracks().empty(),"ClearMapMusic stopped active playback");rejects([&]{scene.play("missing.mp3");},"Missing music");require(!scene.voice(),"Failed music replacement retained old voice");}require(device->voices()==0,"Music destruction retained shared device voices");});
        test("music_ex_fade_and_stop_boundary",[&]{MusicScene scene(archives,3);scene.muted(true);scene.play(track,500,1000);require(scene.voice()->playing() && scene.level()==0 && scene.voice()->milliseconds().first>=490,"PlayMusicEx did not apply offset or silent fade start");auto now=GetTickCount()+100;scene.update(now);scene.update(now+500);require(scene.level()==63 && scene.voice()->volume()==0,"Music fade-in ratio or physical mute differs");scene.update(now+1050);require(scene.level()==127,"Music fade-in did not finish");scene.stop(true);now=GetTickCount()+100;scene.update(now);scene.update(now+1000);require(scene.level()==0 && scene.voice()->playing(),"Fade-out paused before strictly exceeding source duration");scene.update(now+1050);require(scene.paused() && !scene.voice()->playing(),"Music fade-out did not pause after duration");});
        test("music_natural_queue_wait_survives_configuration_clear",[&]{auto fixture=scratch/L"queue.w3x";mpq(fixture,{{"war3mapSkin.txt","[CustomSkin]\nShort_V1=one.wav;two.wav\n"},{"one.wav",pcm()},{"two.wav",pcm()}});auto view=archives.fork();view->mountMap(fixture);MusicScene scene(*view,42);scene.muted(true);scene.play("Short");auto first=scene.currentFile();auto deadline=GetTickCount64()+2000;while(!scene.waiting() && GetTickCount64()<deadline){Sleep(10);scene.update();}require(scene.waiting() && !scene.voice(),"Completed short music did not queue next source member");auto now=GetTickCount();scene.clear();scene.update(now+19900);require(scene.waiting() && !scene.voice(),"Music queue ignored source 20-second gap");scene.update(now+20100);require(scene.voice() && scene.voice()->playing() && scene.currentFile()!=first,"Pending source member was lost after ClearMapMusic");});
        test("music_jass_config_and_main_consume_real_playback",[&]{auto view=archives.fork();view->mountMap(fs::path(argv[1])/L"Maps/(2)BootyBay.w3m");auto world=World::read(*view);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::parse({{"music.j",api,"authored music integration"}})),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();require(session.music() && !session.music()->voice() && session.music()->mapIndex()==-1,"JASS configuration started music");PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();require(session.mainCompleted() && session.music()->voice()->playing() && session.music()->volume()==64 && session.music()->voice()->volume()==0,"Music natives did not consume live shared playback");session.updateAudio();});
        test("music_rng_and_fade_reference_fixture",[&]{std::ofstream file(output/L"music-native.json",std::ios::binary);require(bool(file),"Cannot save music fixture");file<<"{\"rng\":[";bool comma=false;std::vector<unsigned> seeds={0,1,2,47,53,59,61,255,256,65535,65536,0x7fffffff,0x80000000,0xffffffff};unsigned generated=123;for(unsigned i=0;i<64;++i){generated=generated*1664525u+1013904223u;seeds.push_back(generated);}for(auto seed:seeds){AudioRandom random(seed);auto state=random.state();if(comma)file<<',';comma=true;file<<'['<<seed<<','<<state[0]<<','<<state[1]<<",[";for(unsigned i=0;i<64;++i){auto value=random.next();state=random.state();if(i)file<<',';file<<'['<<value<<','<<state[1]<<']';}file<<"]]";}file<<"],\"fade\":[";comma=false;for(unsigned volume:{0u,1u,20u,40u,80u,127u})for(unsigned duration:{1u,50u,100u,1000u,3000u,0x7fffffffu})for(unsigned elapsed:{0u,duration/8,duration/2,duration-1,duration})for(bool out:{false,true}){if(comma)file<<',';comma=true;file<<'['<<volume<<','<<duration<<','<<elapsed<<','<<out<<','<<MusicScene::fadeLevel(volume,elapsed,duration,out)<<']';}file<<"]}\n";file.close();require(bool(file),"Cannot complete music fixture");rejects([]{AudioRandom random;random.index(0);},"Empty sound");});
    }catch(const std::exception& e){std::cout<<"FATAL "<<e.what()<<'\n';++failed;}
    require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded in music tests");std::cout<<"RESULT passed="<<passed<<" failed="<<failed<<'\n';return failed?1:0;
}
